float h1(float x){return fract(sin(x*91.7)*43758.5453);} float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);} float n1(float x){float i=floor(x),f=fract(x);f=f*f*(3.0-2.0*f);return mix(h1(i),h1(i+1.0),f);} float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y);}
float strand(vec2 f, vec2 a, vec2 b, float seed, float amp){ vec2 d=b-a; float L=length(d); vec2 u=d/L; vec2 nn=vec2(-u.y,u.x);
  float s=clamp(dot(f-a,u)/L,0.0,1.0); float tt=floor(iTime*24.0);
  float off=(n1(s*7.0+tt*3.1+seed)-0.5)*amp*1.0+(n1(s*23.0+tt*5.7+seed*3.0)-0.5)*amp*0.35; off*=sin(3.14159*s);
  float dd=abs(dot(f-a,nn)-off) + max(0.0,abs(dot(f-a,u)/L-0.5)-0.5)*L;
  return exp(-dd*dd/6.0)*1.2 + exp(-dd/14.0)*0.55 + exp(-dd/70.0)*0.25; }
void mainImage(out vec4 o, in vec2 f){ f.y=iResolution.y-f.y; float on=step(1.8182,iTime)*step(iTime,99.0000);
  float fl=0.6+0.4*h1(floor(iTime*30.0)); vec2 a=vec2(380.0,1180.0), b=vec2(720.0,1180.0);
  float v=strand(f,a,b,1.0,90.0)+0.6*strand(f,a,b,7.0,63.0);
  v*=on*fl; vec3 c=mix(vec3(0.45,0.62,1.0),vec3(1.0),clamp(v-0.8,0.0,1.0))*v; o=vec4(c,clamp(v,0.0,1.0)); }

